553	        : `网络错误，问卷尚未保存：${err}`}]);
554	      return;
555	    }
556	    if (submitView !== activeView) return;
557	    let data = {};
558	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
559	    if (submitView !== activeView) return;
560	    const saved = creating ? resp.status === 201 : resp.status === 200;
561	    if (saved && data.id !== undefined) {
562	      if (creating) {
563	        // 首次创建成功：这份表单从此绑定到刚创建的编号。刷新首页列表，让新
564	        // 草稿出现在列表中；列表与详情使用同一个编号。
