    # ---------- 加载成功：完整原稿进入表单 ----------

    def test_loaded_form_shows_saved_content_exactly(self):
        """文本题/单选题、必填/选填、顺序、全部选项、中文引号换行均按原稿显示。"""
        survey_id, saved = self.rich_survey()
